using SharpMUTerm.Audio;

namespace SharpMUTerm.Tui.Tests;

/// <summary>miniaudio reads no Vorbis, so an OGG is decoded to a WAV first. The device is not needed for that.</summary>
public class OggDecodeTests
{
    /// <summary>A tenth of a second of 440 Hz, mono, 8 kHz, encoded by oggenc.</summary>
    private const string Tone = "";

    [Test]
    public async Task AnOggBecomesAWavOfTheSameLengthAndShape()
    {
        var path = Path.Combine(Path.GetTempPath(), $"sharpmuterm-tone-{Guid.NewGuid():N}.ogg");
        File.WriteAllBytes(path, Convert.FromBase64String(Tone));
        try
        {
            using var wav = DesktopAudio.OggToWav(path);
            var bytes = wav.ToArray();

            await Assert.That(System.Text.Encoding.ASCII.GetString(bytes, 0, 4)).IsEqualTo("RIFF");
            await Assert.That(System.Text.Encoding.ASCII.GetString(bytes, 8, 4)).IsEqualTo("WAVE");
            await Assert.That(BitConverter.ToInt16(bytes, 22)).IsEqualTo((short)1);  // channels
            await Assert.That(BitConverter.ToInt32(bytes, 24)).IsEqualTo(8000);      // rate
            var samples = BitConverter.ToInt32(bytes, 40) / 2;
            await Assert.That(samples).IsBetween(700, 900);
            await Assert.That(bytes.Length).IsEqualTo(44 + samples * 2);
        }
        finally
        {
            File.Delete(path);
        }
    }

    [Test]
    public async Task AFileThatIsNotVorbisIsRefused()
    {
        var path = Path.Combine(Path.GetTempPath(), $"sharpmuterm-junk-{Guid.NewGuid():N}.ogg");
        File.WriteAllBytes(path, [1, 2, 3, 4, 5, 6, 7, 8]);
        try
        {
            await Assert.That(() => DesktopAudio.OggToWav(path)).Throws<Exception>();
        }
        finally
        {
            File.Delete(path);
        }
    }
}
